import{_ as t,H as a,f as r,i as _}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"Q72 | 选型：如何根据业务评估开源大模型性能？","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q72｜选型：如何根据业务评估开源大模型性能？.md","filePath":"致程序员：AI百问百答/Q72｜选型：如何根据业务评估开源大模型性能？.md","lastUpdated":1795559851000}'),s={name:"致程序员：AI百问百答/Q72｜选型：如何根据业务评估开源大模型性能？.md"};function n(i,e,o,p,E,l){return a(),r("div",null,[...e[0]||(e[0]=[_('<h1 id="q72-选型-如何根据业务评估开源大模型性能" tabindex="-1">Q72 | 选型：如何根据业务评估开源大模型性能？ <a class="header-anchor" href="#q72-选型-如何根据业务评估开源大模型性能" aria-label="Permalink to &quot;Q72 | 选型：如何根据业务评估开源大模型性能？&quot;">​</a></h1><ul><li>作者介绍：彭靖田，Google Developers Expert</li></ul><p>Q：开源大模型很多，如何根据自身业务评估各个开源大模型的性能，挑选出合适的大模型呢？</p><p>彭靖田：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%B4%E7%A8%8B%E5%BA%8F%E5%91%98%EF%BC%9AAI%E7%99%BE%E9%97%AE%E7%99%BE%E7%AD%94/images/Q72/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%B4%E7%A8%8B%E5%BA%8F%E5%91%98%EF%BC%9AAI%E7%99%BE%E9%97%AE%E7%99%BE%E7%AD%94/images/Q72/1.png" alt=""></a></p><p>业务需求匹配：如需要多模态能力，可以选择如 CLIP 或 Gopher 类的模型，生成类任务则适合 GPT、OPT。</p><p>模型性能和准确性：查看模型的 Benchmark 结果，针对特定任务进行测试，如自然语言处理任务可以对比不同模型在 GLUE、 SuperGLUE 等 Benchmark 上的表现。</p><p>推理和训练成本：评估模型大小和推理效率，确定是否符合自身的硬件条件或云服务预算。</p><p>支持和维护：优先选择具有活跃社区支持和频繁更新的开源模型，如 Hugging FaceTransformers 中的 LLaMA、OPT 等。</p>',9)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
